-- ============================================================================
-- GA COACHING V2 - PROGRAM CLOUD V1
-- Moteur stable dans l'app / programmations vivantes dans Supabase.
-- ============================================================================

begin;

create extension if not exists pgcrypto;

create table if not exists public.program_versions_v2 (
  id uuid primary key default gen_random_uuid(),
  athlete_slug text not null,
  program_key text not null,
  version integer not null default 1 check (version > 0),
  status text not null default 'draft'
    check (status in ('draft','active','archived')),
  current_week integer null
    check (current_week is null or current_week > 0),
  program_json jsonb not null,
  notes text null,
  created_by uuid null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz null,
  unique (athlete_slug, program_key, version)
);

create unique index if not exists program_versions_v2_one_active_per_athlete
  on public.program_versions_v2 (athlete_slug)
  where status = 'active';

create index if not exists program_versions_v2_lookup_idx
  on public.program_versions_v2 (
    athlete_slug,
    status,
    version desc
  );

alter table public.program_versions_v2 enable row level security;

drop policy if exists program_versions_v2_read_authenticated
  on public.program_versions_v2;

create policy program_versions_v2_read_authenticated
  on public.program_versions_v2
  for select
  to authenticated
  using (true);

drop policy if exists program_versions_v2_insert_editable
  on public.program_versions_v2;

create policy program_versions_v2_insert_editable
  on public.program_versions_v2
  for insert
  to authenticated
  with check (
    public.can_edit_athlete(athlete_slug)
  );

drop policy if exists program_versions_v2_update_editable
  on public.program_versions_v2;

create policy program_versions_v2_update_editable
  on public.program_versions_v2
  for update
  to authenticated
  using (
    public.can_edit_athlete(athlete_slug)
  )
  with check (
    public.can_edit_athlete(athlete_slug)
  );

drop policy if exists program_versions_v2_delete_editable
  on public.program_versions_v2;

create policy program_versions_v2_delete_editable
  on public.program_versions_v2
  for delete
  to authenticated
  using (
    public.can_edit_athlete(athlete_slug)
  );

revoke all on table public.program_versions_v2
  from anon;

grant select, insert, update, delete
  on table public.program_versions_v2
  to authenticated;

create or replace function public.program_versions_v2_touch_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists program_versions_v2_touch_updated_at
  on public.program_versions_v2;

create trigger program_versions_v2_touch_updated_at
before update
on public.program_versions_v2
for each row
execute function public.program_versions_v2_touch_updated_at();

create or replace function public.save_program_version_v2(
  p_athlete_slug text,
  p_program_key text,
  p_program_json jsonb,
  p_current_week integer default null,
  p_publish boolean default false,
  p_notes text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_version integer;
  v_id uuid;
begin
  if not public.can_edit_athlete(p_athlete_slug) then
    raise exception 'Not allowed to edit athlete %', p_athlete_slug;
  end if;

  if p_program_json is null then
    raise exception 'program_json is required';
  end if;

  select coalesce(max(version), 0) + 1
  into v_version
  from public.program_versions_v2
  where athlete_slug = p_athlete_slug
    and program_key = p_program_key;

  if p_publish then
    update public.program_versions_v2
    set
      status = 'archived',
      updated_at = now()
    where athlete_slug = p_athlete_slug
      and status = 'active';
  end if;

  insert into public.program_versions_v2 (
    athlete_slug,
    program_key,
    version,
    status,
    current_week,
    program_json,
    notes,
    created_by,
    published_at
  )
  values (
    p_athlete_slug,
    p_program_key,
    v_version,
    case when p_publish then 'active' else 'draft' end,
    p_current_week,
    p_program_json,
    p_notes,
    auth.uid(),
    case when p_publish then now() else null end
  )
  returning id
  into v_id;

  return v_id;
end;
$$;

revoke all on function public.save_program_version_v2(
  text,
  text,
  jsonb,
  integer,
  boolean,
  text
) from public, anon;

grant execute on function public.save_program_version_v2(
  text,
  text,
  jsonb,
  integer,
  boolean,
  text
) to authenticated;

create or replace function public.publish_program_version_v2(
  p_id uuid
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.program_versions_v2%rowtype;
begin
  select *
  into v_row
  from public.program_versions_v2
  where id = p_id;

  if not found then
    raise exception 'Program version not found';
  end if;

  if not public.can_edit_athlete(v_row.athlete_slug) then
    raise exception 'Not allowed to edit athlete %', v_row.athlete_slug;
  end if;

  update public.program_versions_v2
  set
    status = 'archived',
    updated_at = now()
  where athlete_slug = v_row.athlete_slug
    and status = 'active'
    and id <> p_id;

  update public.program_versions_v2
  set
    status = 'active',
    published_at = coalesce(published_at, now()),
    updated_at = now()
  where id = p_id;

  return true;
end;
$$;

revoke all on function public.publish_program_version_v2(uuid)
  from public, anon;

grant execute on function public.publish_program_version_v2(uuid)
  to authenticated;

commit;

select pg_notify('pgrst', 'reload schema');




